package dev.thefoolish.generated.anishelf;public final class PlayerActivity extends AppScreen{protected void render(){String id=getIntent().getStringExtra("id"),t=getIntent().getStringExtra("title");int ep=getIntent().getIntExtra("episode",1);String key="progress_"+id+"_"+ep;title((t==null?"Anime":t)+" · Episode "+ep);subtitle("Playback requires a provider media URL. AIDao does not fabricate a playable stream when the provider contract cannot resolve one.");body.addView(text("Saved resume position: "+store.number(key)+" seconds",14,false));android.widget.Button save=button("Save +60s test progress");save.setOnClickListener(v->{store.number(key,store.number(key)+60);store.putText("last_episode",(t==null?"Anime":t)+" · Episode "+ep);recreate();});body.addView(save);nav();}}
